import{_ as a,o as r,c as e,a2 as l}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"مبادئ توزيع «من عمل أكثر نال أكثر»","description":"","frontmatter":{},"headers":[],"relativePath":"ar/0006-多劳多得分配原理.md","filePath":"ar/0006-多劳多得分配原理.md"}'),d={name:"ar/0006-多劳多得分配原理.md"};function i(o,t,h,n,s,c){return r(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="مبادئ-توزيع-«من-عمل-أكثر-نال-أكثر»" tabindex="-1">مبادئ توزيع «من عمل أكثر نال أكثر» <a class="header-anchor" href="#مبادئ-توزيع-«من-عمل-أكثر-نال-أكثر»" aria-label="Permalink to &quot;مبادئ توزيع «من عمل أكثر نال أكثر»&quot;">​</a></h1><table tabindex="0"><thead><tr><th>العنصر</th><th>المحتوى</th></tr></thead><tbody><tr><td>رقم الوثيقة</td><td>06</td></tr><tr><td>الوحدة</td><td>المبادئ العامة والإعدادات الأساسية</td></tr><tr><td>الكلمات المفتاحية</td><td>من عمل أكثر نال أكثر، التوزيع، المساهمة، العقود المرتبطة بالإنتاج، العدالة والكفاءة</td></tr></tbody></table><h2 id="أولاً-التعريف-الأساسي-لمبدأ-«من-عمل-أكثر-نال-أكثر»" tabindex="-1">أولاً: التعريف الأساسي لمبدأ «من عمل أكثر نال أكثر» <a class="header-anchor" href="#أولاً-التعريف-الأساسي-لمبدأ-«من-عمل-أكثر-نال-أكثر»" aria-label="Permalink to &quot;أولاً: التعريف الأساسي لمبدأ «من عمل أكثر نال أكثر»&quot;">​</a></h2><p>«من عمل أكثر نال أكثر» هو مبدأ التوزيع المركزي لحضارة التكافل المرساة: توزيع القيم النادرة كموارد الزراعة والفرص التطورية والأوسمة الاجتماعية يقوم أساساً على المساهمة الفعلية للأفراد أو الجماعات في الشبكة التكافلية. كلما زادت المساهمة، زادت الحصة؛ وكلما قلت المساهمة، قلت الحصة. يعارض هذا المبدأ توزيع الافتراس للمكاسب غير المستحقة، كما يعارض التوزيع المساواتي الذي لا فرق فيه بين أكثر عملاً وأقل عملاً.</p><p>لـ«العمل» معنى محدد في الحضارة التكافلية: فهو لا يشير إلى العمل الجسدي فحسب، بل إلى جميع الأنشطة ذات المساهمات الإيجابية في الشبكة التكافلية، بما فيها الزراعة المجتهدة وخلق المعرفة والابتكار التقني وصيانة المراسي وحوكمة الحضارة والتعاون بين الأعراق. و«النيل» لا يشير أيضاً إلى الموارد المادية فحسب، بل إلى دعم تطوري شامل يشمل الفرص التطورية وتصاريح الوصول إلى المراسي ومؤهلات الإرشاد والأولوية في استكشاف المستويات.</p><h2 id="ثانياً-الأسس-النظرية-لمبدأ-«من-عمل-أكثر-نال-أكثر»" tabindex="-1">ثانياً: الأسس النظرية لمبدأ «من عمل أكثر نال أكثر» <a class="header-anchor" href="#ثانياً-الأسس-النظرية-لمبدأ-«من-عمل-أكثر-نال-أكثر»" aria-label="Permalink to &quot;ثانياً: الأسس النظرية لمبدأ «من عمل أكثر نال أكثر»&quot;">​</a></h2><p>يقوم وضع هذا المبدأ على الاعتبارات النظرية الثلاثة التالية:</p><h3 id="_2-1-نظرية-الحوافز-المساهمات-تحتاج-تغذية-راجعة-إيجابية" tabindex="-1">2.1 نظرية الحوافز: المساهمات تحتاج تغذية راجعة إيجابية <a class="header-anchor" href="#_2-1-نظرية-الحوافز-المساهمات-تحتاج-تغذية-راجعة-إيجابية" aria-label="Permalink to &quot;2.1 نظرية الحوافز: المساهمات تحتاج تغذية راجعة إيجابية&quot;">​</a></h3><p>التطور عملية تتطلب استثماراً مستمراً. إذا انفصلت المساهمة عن النيل، يفقد الأفراد دافع الاستثمار المستمر، وتنخفض الكفاءة التطورية للشبكة التكافلية بأكملها. عبر إنشاء حلقة تغذية راجعة إيجابية بين المساهمة والنيل، يحفز «من عمل أكثر نال أكثر» كل كائن على تعظيم إمكاناته الخاصة وخلق مزيد من القيمة للشبكة التكافلية.</p><h3 id="_2-2-نظرية-العدالة-التوزيع-حسب-المساهمة-هو-أقصى-درجات-العدالة" tabindex="-1">2.2 نظرية العدالة: التوزيع حسب المساهمة هو أقصى درجات العدالة <a class="header-anchor" href="#_2-2-نظرية-العدالة-التوزيع-حسب-المساهمة-هو-أقصى-درجات-العدالة" aria-label="Permalink to &quot;2.2 نظرية العدالة: التوزيع حسب المساهمة هو أقصى درجات العدالة&quot;">​</a></h3><p>في الحضارة التكافلية، العدالة لا تساوي المساواة المطلقة. العدالة الحقيقية تعني أن جهد كل كائن ينال مكافأة مقابلة. فالمزارع الذي يبلغ مرتبة عالية بالزراعة المجتهدة وينال موارد وفرصاً أكثر هو مكافأة معقولة لجهده؛ والفرد الذي لا يبذل أي جهد ولا ينال سوى الضمان الأساسي هو أيضاً تعبير عن العدالة. يحمي «من عمل أكثر نال أكثر» حقوق المجتهدين والمبدعين.</p><h3 id="_2-3-نظرية-الكفاءة-الموارد-يجب-أن-تتدفق-حيث-تخلق-أقصى-قيمة" tabindex="-1">2.3 نظرية الكفاءة: الموارد يجب أن تتدفق حيث تخلق أقصى قيمة <a class="header-anchor" href="#_2-3-نظرية-الكفاءة-الموارد-يجب-أن-تتدفق-حيث-تخلق-أقصى-قيمة" aria-label="Permalink to &quot;2.3 نظرية الكفاءة: الموارد يجب أن تتدفق حيث تخلق أقصى قيمة&quot;">​</a></h3><p>رغم أن موارد الزراعة الكونية يمكن زيادتها باستمرار بالوسائل التقنية، فإنها تظل محدودة في زمان ومكان معين. تعطي آلية «من عمل أكثر نال أكثر» الأولوية لتخصيص الموارد للأفراد والجماعات ذات المساهمة والكفاءة العالية، بما يمكن الموارد المحدودة من إنتاج أقصى فائدة تطورية. وهذا ليس تخلياً عن الضعفاء، بل مسؤولية تجاه الكفاءة التطورية الكلية — ففقط بعد تحسين الكفاءة الكلية يمكن توفير مزيد من الموارد لحماية الضعفاء.</p><h2 id="ثالثاً-نظام-التقييم-الكمي-للمساهمات" tabindex="-1">ثالثاً: نظام التقييم الكمي للمساهمات <a class="header-anchor" href="#ثالثاً-نظام-التقييم-الكمي-للمساهمات" aria-label="Permalink to &quot;ثالثاً: نظام التقييم الكمي للمساهمات&quot;">​</a></h2><p>لكي يصبح مبدأ «من عمل أكثر نال أكثر» قابلاً للتطبيق، أنشأت الحضارة التكافلية نظاماً منهجياً للتقييم الكمي للمساهمات:</p><table tabindex="0"><thead><tr><th>نوع المساهمة</th><th>بُعد التقييم</th><th>طريقة التحديد الكمي</th></tr></thead><tbody><tr><td>مساهمة الزراعة</td><td>سرعة ترقي المرتبة، ارتفاع المرتبة، الأثر الإرشادي للاختراقات</td><td>تسجل شبكة المراسي بيانات الزراعة تلقائياً، وتحولها إلى قيمة مساهمة زراعية</td></tr><tr><td>مساهمة المعرفة</td><td>المشاركة العامة بخلاصات الزراعة، وخلق طرق جديدة، ونتائج البحث النظري</td><td>تقيّمها اللجنة الأكاديمية، وتُقيَّم بتأثير المعرفة وابتكاريتها</td></tr><tr><td>المساهمة التقنية</td><td>الابتكار التقني في هندسة القوانين، وتحسين تطبيقات ثمرة المضاعفة، وتحسين معدات المراسي</td><td>تقيّمها اللجنة التقنية، وتُقيَّم بالفائدة العملية ونطاق التعميم</td></tr><tr><td>مساهمة الخدمة</td><td>ساعات الإرشاد، وعبء عمل صيانة المراسي، والمشاركة في حوكمة الحضارة</td><td>تسجل شبكة المراسي مدة الخدمة وجودتها تلقائياً، وتحولها إلى قيمة مساهمة خدمية</td></tr><tr><td>المساهمة البيئية</td><td>استعادة النظم البيئية للكواكب، وتحسين تداول الطاقة بين المستويات، وحماية البيئة الكونية</td><td>تقيّمها اللجنة البيئية، وتُقيَّم بنطاق التحسين البيئي واستدامته</td></tr><tr><td>المساهمة التعاونية</td><td>المشاركة في مشاريع التعاون بين الأعراق، والإسهام في شؤون جمهورية عشرة آلاف عرق</td><td>تقيّمها الجمعية الجمهورية، وتُقيَّم بعمق التعاون ونتائجه</td></tr></tbody></table><p>القيمة الإجمالية لمساهمة الفرد هي المجموع الموزون لجميع أنواع قيم المساهمات، مع ضبط الأوزان ديناميكياً حسب احتياجات مرحلة تطور الحضارة. تُصفَّى قيم المساهمات كل ثلاثة أشهر، لتكون الأساس الرئيسي لتوزيع موارد الربع التالي.</p><h2 id="رابعاً-نظام-العقود-المرتبطة-بالإنتاج" tabindex="-1">رابعاً: نظام العقود المرتبطة بالإنتاج <a class="header-anchor" href="#رابعاً-نظام-العقود-المرتبطة-بالإنتاج" aria-label="Permalink to &quot;رابعاً: نظام العقود المرتبطة بالإنتاج&quot;">​</a></h2><p>العقد المرتبط بالإنتاج هو التصميم المؤسسي الملموس لمبدأ «من عمل أكثر نال أكثر» في مجال توزيع موارد الزراعة، وفكرته الأساسية «التعاقد على الإنتاج مع الجماعات، والدفع حسب الإنتاج، ومكافأة فائض الإنتاج».</p><h3 id="_4-1-التشغيل-الأساسي" tabindex="-1">4.1 التشغيل الأساسي <a class="header-anchor" href="#_4-1-التشغيل-الأساسي" aria-label="Permalink to &quot;4.1 التشغيل الأساسي&quot;">​</a></h3><ol><li><strong>التعاقد على الموارد</strong>: توكل الحضارة التكافلية موارد الزراعة في منطقة معينة (كعروق الأرواح وحقول الأدوية وعروق المعادن الطاقية) إلى جماعات المزارعين أو المجتمعات العرقية</li><li><strong>حصة الإنتاج</strong>: تُحدد حصة إنتاج معقولة بناءً على الإنتاجية الأساسية للمورد وقدرة المتعاقد</li><li><strong>الدفع المرتبط بالإنتاج</strong>: ترتبط حصة الموارد التي يحصل عليها المتعاقد بالإنتاج الفعلي؛ بلوغ الحصة يمنح الحصة الأساسية، وفائض الإنتاج يُكافأ نسبياً</li><li><strong>التشغيل الذاتي</strong>: ما دام المتعاقد لا يخالف مبدأ مكافحة الافتراس ولوائح الحماية البيئية، فله الحق في أن يقرر ذاتياً طرق تطوير الموارد واستخدامها</li></ol><h3 id="_4-2-مزايا-العقد-المرتبط-بالإنتاج" tabindex="-1">4.2 مزايا العقد المرتبط بالإنتاج <a class="header-anchor" href="#_4-2-مزايا-العقد-المرتبط-بالإنتاج" aria-label="Permalink to &quot;4.2 مزايا العقد المرتبط بالإنتاج&quot;">​</a></h3><ul><li>يربط مباشرة كفاءة استخدام الموارد الجماعية بمصالح المتعاقد الشخصية، محفزاً على الزراعة المتقنة</li><li>يتجنب «مأساة المشاعات» الناتجة عن التوزيع المتساوي للموارد، محسناً كفاءة استخدام الموارد</li><li>تحت حافز مكافآت فائض الإنتاج، يُحفز المتعاقدون على الابتكار التقني وتحسين الإدارة</li><li>يوفر للمزارعين قناة مستقرة للحصول على الموارد، مخففاً الدافع الاقتصادي للسلوك الافتراسي</li></ul><h3 id="_4-3-الحماية-من-المخاطر" tabindex="-1">4.3 الحماية من المخاطر <a class="header-anchor" href="#_4-3-الحماية-من-المخاطر" aria-label="Permalink to &quot;4.3 الحماية من المخاطر&quot;">​</a></h3><p>لا ينقل العقد المرتبط بالإنتاج كل المخاطر إلى المتعاقد. أنشأت الحضارة التكافلية «صندوق الحماية من مخاطر العقود»، يقدم حماية أساسية للمتعاقدين في حالات الكوارث الطبيعية القاهرة أو تموجات المستويات، بما يضمن ألا يفقدوا ظروف الزراعة الأساسية بسبب الحوادث.</p><h2 id="خامساً-التوازن-بين-الضمان-الأساسي-و«من-عمل-أكثر-نال-أكثر»" tabindex="-1">خامساً: التوازن بين الضمان الأساسي و«من عمل أكثر نال أكثر» <a class="header-anchor" href="#خامساً-التوازن-بين-الضمان-الأساسي-و«من-عمل-أكثر-نال-أكثر»" aria-label="Permalink to &quot;خامساً: التوازن بين الضمان الأساسي و«من عمل أكثر نال أكثر»&quot;">​</a></h2><p>لا يعني «من عمل أكثر نال أكثر» أن الحضارة التكافلية «مجتمع غابة» كامل. بل على العكس، يجب أن يقترن «من عمل أكثر نال أكثر» بالضمان الأساسي لـ«طريق لكل إنسان» لتحقيق وحدة العدالة والكفاءة.</p><p>أنشأت الحضارة التكافلية «خط الضمان التطوري الأساسي»، الذي يضمن أن يحصل كل كائن، بغض النظر عن مساهمته، على الحمايات الأساسية التالية:</p><ul><li>الوصول المجاني إلى الطرق الأساسية لأنظمة الزراعة الأصلية الثلاثمائة</li><li>الحد الأدنى من تخصيص موارد الزراعة (الكافي لاستمرار الزراعة والبقاء الأساسيين)</li><li>الخدمات الطبية والتعليمية الأساسية</li><li>الوصول إلى الحد الأدنى من مستوى شبكة المراسي</li></ul><p>وفوق خط الضمان الأساسي، يتبع توزيع الموارد بدقة مبدأ «من عمل أكثر نال أكثر». هذه البنية المزدوجة «الضمان الأدنى + التوزيع حسب المساهمة» تحمي الحقوق التطورية الأساسية للضعفاء وتحفز خلق وإسهام الأقوياء معاً.</p><h2 id="سادساً-آليات-منع-انحراف-«من-عمل-أكثر-نال-أكثر»" tabindex="-1">سادساً: آليات منع انحراف «من عمل أكثر نال أكثر» <a class="header-anchor" href="#سادساً-آليات-منع-انحراف-«من-عمل-أكثر-نال-أكثر»" aria-label="Permalink to &quot;سادساً: آليات منع انحراف «من عمل أكثر نال أكثر»&quot;">​</a></h2><p>قد يواجه المبدأ خطر الانحراف في الممارسة، وقد أنشأت الحضارة التكافلية الآليات الوقائية التالية:</p><ul><li><strong>آلية مكافحة الاحتكار</strong>: تمنع الأفراد أو الجماعات من الحصول على مساهمات فائضة غير معقولة عبر احتكار الموارد؛ ولقانون مكافحة الاحتكار أحكام صريحة</li><li><strong>آلية العدالة بين الأجيال</strong>: لا يمكن توريث قيم المساهمات بالكامل، لمنع تصلب الطبقات الناتج عن «المساهمة الموروثة»</li><li><strong>التحقق من صحة المساهمات</strong>: تعبر شبكة المراسي وتتحقق من بيانات المساهمات، لمنع الإبلاغ الكاذب</li><li><strong>آلية الضبط الديناميكي</strong>: تُعدل أوزان ومعايير تقييم المساهمات دورياً حسب احتياجات التطور الحضاري، لمنع التضخم المفرط لنوع واحد من المساهمات</li></ul><h2 id="الخاتمة" tabindex="-1">الخاتمة <a class="header-anchor" href="#الخاتمة" aria-label="Permalink to &quot;الخاتمة&quot;">​</a></h2><p>«من عمل أكثر نال أكثر» هو المبدأ المركزي لنظام التوزيع في حضارة التكافل المرساة. وهو يختلف عن «الأقوى يستحوذ على كل شيء» في الافتراسية، وعن «القدر المشترك» في المساواة المطلقة؛ فعلى أساس الضمان الأساسي، يوزع الموارد والفرص حسب المساهمة، محققاً وحدة العدالة والكفاءة. الهدف النهائي لهذا المبدأ هو ضمان أن يكون لجهد كل كائن مقابل، وأن تتحقق إمكانات كل كائن بالكامل.</p><h2 id="الوثائق-ذات-الصلة" tabindex="-1">الوثائق ذات الصلة <a class="header-anchor" href="#الوثائق-ذات-الصلة" aria-label="Permalink to &quot;الوثائق ذات الصلة&quot;">​</a></h2><ul><li>08-人人有路保障体系 (نظام ضمان «طريق لكل إنسان»)</li><li>22-资源分配联产承包机制 (نظام العقود المرتبطة بالإنتاج لتوزيع الموارد)</li><li>41-共生劳动法 (قانون العمل التكافلي)</li></ul>',37)])])}const p=a(d,[["render",i]]);export{_ as __pageData,p as default};
